package codeflow

import codeflow.java.AstReader
import java.nio.file.FileVisitOption
import java.nio.file.Files
import java.nio.file.Path
import kotlin.system.exitProcess

/**
 * `--from`, `--boundary` and `--pure` take a value and may be repeated, so the arguments cannot be read as "the one that is not a flag".
 *
 * `codeflow src --from App#run` would otherwise take `App#run` for the source directory - it does
 * not start with `--` - and fail on a path that was never meant to be one. Both spellings are
 * accepted because both are what people type.
 */
private class Args(given: Array<String>) {
    var directory: String? = null
        private set
    val from = ArrayList<String>()
    val boundaries = ArrayList<String>()
    val pures = ArrayList<String>()
    val flags = HashSet<String>()
    var level: String? = null
        private set

    init {
        val argv = expandArgumentFiles(given)
        var i = 0
        while (i < argv.size) {
            val arg = argv[i]
            when {
                arg == "--from" -> {
                    from.add(argv.getOrNull(i + 1) ?: throw IllegalArgumentException("--from needs a Class#method"))
                    i++
                }
                arg.startsWith("--from=") -> from.add(arg.removePrefix("--from="))
                arg == "--boundary" -> {
                    boundaries.add(argv.getOrNull(i + 1) ?: throw IllegalArgumentException("--boundary needs a Class"))
                    i++
                }
                arg.startsWith("--boundary=") -> boundaries.add(arg.removePrefix("--boundary="))
                arg == "--pure" -> {
                    pures.add(argv.getOrNull(i + 1) ?: throw IllegalArgumentException("--pure needs a Class"))
                    i++
                }
                arg.startsWith("--pure=") -> pures.add(arg.removePrefix("--pure="))
                arg == "--level" -> {
                    val value = argv.getOrNull(i + 1) ?: throw IllegalArgumentException("--level needs one of ${LEVELS.sorted()}")
                    require(value in LEVELS) { "unknown level '$value'; expected one of ${LEVELS.sorted()}" }
                    level = value
                    i++
                }
                arg.startsWith("--level=") -> {
                    val value = arg.removePrefix("--level=")
                    require(value in LEVELS) { "unknown level '$value'; expected one of ${LEVELS.sorted()}" }
                    level = value
                }
                // An unknown flag is refused rather than ignored. The exporter chain ends in Mermaid,
                // so a flag nobody recognises used to produce a complete, plausible document that is
                // not the one asked for - a mistyped `--html`, or `--html-cytoscape` after the second
                // renderer was removed, and nothing on stdout or stderr saying so.
                arg.startsWith("--") -> {
                    require(arg in KNOWN_FLAGS) { "unknown flag $arg; expected one of ${KNOWN_FLAGS.sorted()}" }
                    flags.add(arg)
                }
                directory == null -> directory = arg
            }
            i++
        }
    }

    companion object {
        val FORMATS = setOf("--html", "--json", "--graphml", "--summaries")
        val OPTIONS = setOf("--assume-single-impl", "--auto-boundaries", "--discover-roots")
        val KNOWN_FLAGS = FORMATS + OPTIONS
        val LEVELS = setOf("architecture", "workflow", "expressions")
    }
}

/**
 * Each `@path` replaced by the arguments that file holds, javac's convention: every line split on
 * whitespace, blank lines and lines starting `#` skipped. Not recursive - an `@` inside the file is an
 * ordinary argument. So a set of roots and boundaries lives in a file a person edits, rather than in a
 * shell history.
 *
 * A file that cannot be read fails, naming it: run without the roots and boundaries it held, the
 * document would be a complete graph of something other than what was asked for.
 */
internal fun expandArgumentFiles(argv: Array<String>): List<String> = argv.flatMap { arg ->
    if (!arg.startsWith("@")) return@flatMap listOf(arg)
    val path = Path.of(arg.removePrefix("@"))
    require(Files.isRegularFile(path)) { "arguments file $path not found" }
    Files.readAllLines(path)
        .map { it.trim() }
        .filter { it.isNotEmpty() && !it.startsWith("#") }
        .flatMap { it.split(Regex("\\s+")) }
}

fun main(argv: Array<String>) {
    val status = runCli(argv)
    if (status != 0) exitProcess(status)
}

/**
 * The whole run, with its exit status returned rather than taken: `main` exits, a test that calls
 * this does not take its JVM down when a fixture gains a construct nothing models.
 */
internal fun runCli(argv: Array<String>): Int {
    val args = Args(argv)
    val javaRootDir = args.directory ?: throw IllegalArgumentException("usage: codeflow <dir> [--from Class#method] [--boundary Class] [--pure Class]")
    // Source paths come back from javac as absolute URIs, and AstReader relativizes them
    // against this one. Path.relativize throws if only one of the two is absolute.
    val javaRootDirPath = Path.of(javaRootDir).toAbsolutePath().normalize()

    val filesPaths = generateListOfJavaFilesFromDir(javaRootDirPath)
    val reader = AstReader(javaRootDirPath)
    val assumeSingleImpl = args.flags.contains("--assume-single-impl")
    val autoBoundaries = args.flags.contains("--auto-boundaries")
    val discoverRoots = args.flags.contains("--discover-roots")
    if (args.flags.contains("--summaries")) {
        val document = SummariesExporter().document(
            reader.summarise(filesPaths, args.from, args.boundaries, args.pures, assumeSingleImpl, autoBoundaries)
        )
        println(document.text)
        System.err.println("codeflow: summarised ${document.methods} methods, ${document.pairs} pairs, ${document.gaps} gaps")
        return if (reader.unmodelled.isNotEmpty()) 1 else 0
    }
    val roots = reader.process(filesPaths, args.from, args.boundaries, args.pures, assumeSingleImpl, autoBoundaries, discoverRoots)

    val result = ArrayList<String>()
    // Both renderings go to stdout, which is the document; the diagnostics AstReader prints are on
    // stderr, so redirecting stdout to a file gives something a viewer can open directly.
    if (args.flags.contains("--html")) {
        HtmlExporter("reactflow.bundle.js", javaRootDirPath, args.level).processMainMethod(roots) { result.add(it) }
    } else if (args.flags.contains("--json")) {
        JsonExporter(javaRootDirPath, args.level).processMainMethod(roots) { result.add(it) }
    } else if (args.flags.contains("--graphml")) {
        GraphmlExporter().processMainMethod(roots) { result.add(it) }
    } else {
        MermaidExporter().processMainMethod(roots) { result.add(it) }
    }

    result.forEach { println(it) }

    // The document is complete and usable, so it is written first and in full; the status is what
    // says whether everything in it was understood. A build that graphs a corpus can fail on this
    // and get the diagram anyway, which is the point of no longer throwing - see `codeflow.ir`.
    return if (reader.unmodelled.isNotEmpty()) 1 else 0
}

fun generateListOfJavaFilesFromDir(dir: Path): List<Path> {
    return Files.walk(dir, FileVisitOption.FOLLOW_LINKS)
        .filter { it.toString().endsWith(".java") }
        .toList()
}
